sol = [0, 8, 30, 33, 10, 1, 29, 11, 32, 19, 26, 6, 3, 14, 31, 9, 28, 4]
edges = []
for g in range(6):
    for i in range(3):
        for j in range(i+1,3):
            edges.append((3*g+i, 3*g+j))
for g in range(5):
    for i in range(3):
        edges.append((3*g+i, 3*(g+1)+i))

